import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().start();
    }

    void start() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] basePoly = new int[10];
        for (int i = 0; i < k; i++) {
            basePoly[in.nextInt()] = 1;
        }
        int[] resultPoly = new int[]{1};
        int power = n / 2;
        while (true) {
            if ((power & 1) == 1) {
                resultPoly = multiply(resultPoly, basePoly, MOD);
            }
            power >>>= 1;
            if (power == 0) break;
            basePoly = multiply(basePoly, basePoly, MOD);
        }
        long answer = 0;
        for (int val : resultPoly) {
            answer = (answer + (long)val * val) % MOD;
        }
        out.println(answer);
        out.close();
    }

    int[] multiply(int[] p1, int[] p2, int mod) {
        int requiredLength = p1.length + p2.length - 1;
        int fftSize = 1;
        while (fftSize < requiredLength) fftSize <<= 1;

        double[] re1 = new double[fftSize];
        double[] im1 = new double[fftSize];
        for (int i = 0; i < p1.length; i++) {
            long val = ((long)p1[i] % mod + mod) % mod;
            re1[i] = val & 0x7FFF;
            im1[i] = val >>> 15;
        }

        performFFT(re1, im1, false);

        double[] re2 = new double[fftSize];
        double[] im2 = new double[fftSize];
        if (p1 == p2) {
            System.arraycopy(re1, 0, re2, 0, fftSize);
            System.arraycopy(im1, 0, im2, 0, fftSize);
        } else {
            for (int i = 0; i < p2.length; i++) {
                long val = ((long)p2[i] % mod + mod) % mod;
                re2[i] = val & 0x7FFF;
                im2[i] = val >>> 15;
            }
            performFFT(re2, im2, false);
        }

        double[] resRe = new double[fftSize];
        double[] resIm = new double[fftSize];
        double normalization = 0.25 / fftSize;

        for (int i = 0; i < fftSize; i++) {
            int j = (fftSize - i) & (fftSize - 1);

            double A1r = re1[i] + re1[j];
            double A1i = im1[i] - im1[j];
            double A2r = im1[i] + im1[j];
            double A2i = re1[j] - re1[i];

            double B1r = (re2[i] + re2[j]) * normalization;
            double B1i = (im2[i] - im2[j]) * normalization;
            double B2r = (im2[i] + im2[j]) * normalization;
            double B2i = (re2[j] - re2[i]) * normalization;

            resRe[i] = A1r * B1r - A1i * B1i - A2r * B2i - A2i * B2r;
            resIm[i] = A1r * B1i + A1i * B1r + A2r * B2r - A2i * B2i;
        }

        performFFT(resRe, resIm, true);

        int[] output = new int[requiredLength];
        for (int i = 0; i < requiredLength; i++) {
            long realComponent = Math.round(resRe[i]);
            long imagComponent = Math.round(resIm[i]);
            output[i] = (int)((realComponent + ((imagComponent % mod) << 15)) % mod);
        }
        return output;
    }

    void performFFT(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            while ((j & bit) != 0) {
                j ^= bit;
                bit >>= 1;
            }
            j ^= bit;
            if (i < j) {
                double temp = re[i]; re[i] = re[j]; re[j] = temp;
                temp = im[i]; im[i] = im[j]; im[j] = temp;
            }
        }

        for (int segment = 2; segment <= n; segment <<= 1) {
            int half = segment >> 1;
            double[] cosines = new double[half];
            double[] sines = new double[half];
            double angle = 2 * Math.PI / segment * (inverse ? -1 : 1);
            for (int i = 0; i < half; i++) {
                cosines[i] = Math.cos(i * angle);
                sines[i] = Math.sin(i * angle);
            }

            for (int start = 0; start < n; start += segment) {
                for (int offset = 0; offset < half; offset++) {
                    double ur = re[start + offset];
                    double ui = im[start + offset];
                    double vr = re[start + offset + half] * cosines[offset] - im[start + offset + half] * sines[offset];
                    double vi = re[start + offset + half] * sines[offset] + im[start + offset + half] * cosines[offset];

                    re[start + offset] = ur + vr;
                    im[start + offset] = ui + vi;
                    re[start + offset + half] = ur - vr;
                    im[start + offset + half] = ui - vi;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream source;
        private final byte[] data = new byte[1024];
        private int current, end;

        public InputReader(InputStream source) {
            this.source = source;
        }

        private int fetch() {
            if (end == -1) throw new InputMismatchException();
            if (current >= end) {
                current = 0;
                try { end = source.read(data); } catch (IOException e) { throw new InputMismatchException(); }
                if (end <= 0) return -1;
            }
            return data[current++] & 0xFF;
        }

        public int nextInt() {
            int c = fetch();
            while (c <= 32) c = fetch();
            int sign = 1;
            if (c == '-') { sign = -1; c = fetch(); }
            int value = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + c - '0';
                c = fetch();
            }
            return value * sign;
        }
    }
}
